APPLICATION = ['PROGRESS: the preceding authoritative proof round was independently rechecked before edits. All 747 baseline source/configuration hashes are checked before registration. Retained proof sources, StrongStatement, toolchain pins and attribution are unchanged; among retained sources only root imports and the exact-name kernel registry change. The fixed local paper is checked against its pinned Git objects without remote updates. The intervening prize heartbeat was a read-only status check, separate from this proof work.', 'NativeLieShiftedExponential is the actual original relative curve in the actual identity chart at time one. Its base value is the actual chart coordinate of identity, which is not assumed zero. The true derivative equals the already proved original native dexp. Actual C-infinity regularity upgrades it to strict differentiability. The actual unit dexp supplies a continuous linear equivalence, and the genuine Banach inverse-function theorem constructs the real shifted local inverse, with both local inverse laws, exact base value, actual strict derivative and actual C-infinity regularity. No inverse function or chart normalization is supplied.', 'NativeLieExponentialLocalLogAt constructs log-v(g)=v+shifted-inverse-v(chart-1(Exp(v)^-1*g)) on the original group. It proves its actual base value and native C-infinity regularity. Translating the actual coordinate inverse laws gives the left inverse near v. For the right inverse, both original relative group points are proved to remain in the true chart source before applying actual chart injectivity and original group cancellation. Thus both laws hold for the original native exponential at every original vector; no global inverse is claimed.', 'NativeLieExponentialLocalHomeomorph uses the actual local logarithm to prove that images of true neighborhoods are true neighborhoods, hence the original exponential is open. Its actual left inverse proves genuine local injectivity. Continuous, injective, open restrictions prove the original exponential is a local homeomorphism. The actual neighborhood map equality, open exponential range and closed discrete original fibers follow. Neither a covering map nor range equal to the whole group follows from these statements alone.', 'NilpotentFiniteExponentialKernel factors the actual finite exponential series minus one as B times a genuine constant-one polynomial. The retained proved polynomial-unit theorem gives a true unit, and genuine cancellation proves B=0 if that finite exponential equals one. The proof works in an arbitrary possibly noncommutative algebra and covers the zero cutoff without silently assuming nontriviality.', 'NativeLieExponentialCentralKernel instantiates this actual finite polynomial factor with the original group-class adjoint formula. Exp(v)=1 implies the derivative-defined original native adjoint generator is zero, and therefore the actual original native bracket [v,w] is zero for every w. The genuine original adjoint curve then equals identity at every real time. This restricts periods to original Lie-algebra central directions; it does not eliminate them.', 'NativeLieAdjointKernelCenter proves identity original adjoint means commutation with the actual original exponential range. The already proved true identity-neighborhood image puts an identity neighborhood inside the actual centralizer. The original Lie group supplies the actual topological-group structure; the centralizer is genuinely open and closed, so original connectedness proves it is the whole group. Conversely, an actual central element has identity conjugation and hence identity actual native derivative. Thus ker(Ad)=the actual group center. Every original exponential period has its entire original one-parameter curve in the center. No connected or simply connected substitute group is introduced.', 'Six new modules contain 35 proved theorems and five definitions, giving 40 exact new kernel reports. Actual full-build and full-kernel terminal exit-zero results, raw byte hashes, current oleans, exact root imports and exact registry are required before recording. The complete own and attributed source tree is scanned for executable trust bypasses. All retained axiom sets and the six retained axiom-free reports remain unchanged. Only propext, Classical.choice and Quot.sound are allowed.', 'Remaining: the original global exponential inverse and BCH for arbitrary connected simply connected nilpotent Lie groups are still unproved. Local homeomorphism and closed discrete fibers do not by themselves prove a covering map, surjectivity or injectivity. Central periods still need a genuine elimination argument using the original structure. Individual group/Lie lower-central layer comparison, faithful integration/Malcev comparison, arbitrary specified-lattice rational subgroup cocompactness, full calibration/Alignment and ordered positive arithmetic witness extraction remain. Nonabelian lattice logarithms are not assumed additive. StrongConjecture and the prize target are not proved; publication and prize submission still await the complete proof and audit. No unavoidable blocker is established.']

COMPONENTS = ['actual original shifted exponential chart has strict invertible derivative and a genuine C-infinity coordinate local inverse at every original vector', 'actual original native exponential has a constructed native C-infinity local logarithm with both local inverse laws at every original vector', 'actual original native exponential is a local homeomorphism and open map with exact neighborhood images and closed discrete fibers', 'actual finite exponential of a nilpotent algebra element equals one only if that element is zero, by genuine polynomial-unit cancellation', 'actual original native exponential periods have zero original adjoint generator and zero native bracket with every original vector', 'actual original connected Lie-group adjoint kernel equals its original group center and original exponential period curves lie entirely in that center']

NEW_PROGRESS = "The actual original native adjoint generators act as the original native Lie bracket. Original group lower-central termination forces every same-length ordered generator product to vanish and hence native Lie lower-central termination at the same cutoff. Thus original Group.IsNilpotent proves native LieModule.IsNilpotent, and genuine original adjoints have finite formulas at original Group.nilpotencyClass. The actual relative curve r-v(t,w)=gamma-v(-t)*gamma-(v+w)(t) now has proved original group cocycle, actual C-infinity regularity and zero-time velocity w. Its genuine original manifold state derivative K-v(t) is identified with its actual identity-chart Jacobian, is C-infinity and has actual initial value zero. Genuine mixed second-derivative symmetry applied to this original relative curve proves K-v'(0)=id. Differentiating the actual group cocycle proves K-v(t+s)=Ad-gamma-v(-t)*K-v(s)+K-v(t), and real time translation gives the actual global derivative K-v'(t)=Ad-gamma-v(-t). A directly differentiated finite polynomial primitive and actual zero-derivative uniqueness prove K-v(t)=sum(j<c) ((-1)^j/(j+1)!)*t^(j+1) times B-v^j, where c is the original group nilpotencyClass and B-v is the actual native bracket generator. Original manifold chain rules identify K-v(1) with the actual original exponential differential followed by actual inverse left translation. Thus the original native dexp now has its genuine finite formula sum(j<c) (-1)^j/(j+1)! times B-v^j, and the full original exponential derivative is actual left translation composed with that operator. Nilpotency and the actual constant-one finite polynomial prove native dexp is a genuine two-sided unit and bijective at every original model vector; actual inverse translation derivatives prove the complete original exponential derivative is likewise a two-sided unit and bijective. The zero group-class case is covered through the proved identity 1=0 for the resulting operator ring, without a nontriviality premise. No dexp formula, variation equation, derivative invertibility, native Lie nilpotency or matrix replacement is supplied. Individual group/Lie lower-central layer identification and global exponential invertibility/BCH still remain unproved; pointwise invertible derivatives alone do not give a global inverse. The actual original shifted exponential coordinate map now has a genuine strict invertible derivative and a C-infinity local inverse at every original vector, from the actual Banach inverse-function theorem. Its actual identity-chart base coordinate is retained, not assumed zero. The constructed original native local logarithm has true native C-infinity regularity and both local inverse laws; actual chart-source control is proved for the group-valued right law. Thus the original native exponential is a genuine local homeomorphism and open map, with exact neighborhood images, open range and closed discrete fibers. A finite nilpotent exponential factor and true constant-one polynomial unit prove every original exponential period has zero actual adjoint generator, hence zero original native bracket with every vector. Identity original adjoint is proved equivalent to actual group centrality in the original connected group, using the actual open centralizer and genuine connectedness. The entire original one-parameter curve of each period lies in the original center. These facts do not prove a covering map, global surjectivity or injectivity; original central periods have not yet been eliminated."


def record():
    from importlib.util import spec_from_file_location, module_from_spec
    baseline, registration, files, verified, blog, alog, fixed = checks()
    manifest = obj("verification-manifest.json")
    assert manifest["files"] == baseline["files"] and manifest["full_target_proved"] is False
    assert len(manifest["proved_components"]) == 822
    assert not set(COMPONENTS) & set(manifest["proved_components"])
    spec = spec_from_file_location("previous_audit_body", OLD + "-audit.py")
    previous = module_from_spec(spec)
    spec.loader.exec_module(previous)
    remaining = manifest["last_round"]["remaining"]
    assert remaining.count(previous.NEW_PROGRESS) == 1
    remaining = remaining.replace(previous.NEW_PROGRESS, NEW_PROGRESS)
    review = {
        "date": "2026-10-10", "classification": "PROGRESS", "previous_goal_turn_classification": "PROGRESS",
        "full_target_proved": False, "baseline_hash_count": 747,
        "retained_changed": ["Hindman168.lean", "Verification.lean"],
        "new_modules": registration["new_modules"], "new_theorem_count": 35,
        "new_selected_report_count": 40, "module_report_counts": registration["module_report_counts"],
        "application_review": APPLICATION, "verification": verified, "remaining": remaining,
    }
    manifest.update(
        date="2026-10-10", files=files, build_succeeded=True, axiom_check_succeeded=True,
        hindman_module_count=verified["project_modules"], pntplus_module_count=verified["pntplus_modules"],
        selected_axiom_report_count=verified["axiom_reports"], source_scan_module_count=verified["source_scan_modules"],
        build_job_count=verified["build_jobs"], build_log=PREFIX + "-build.txt", axiom_log=PREFIX + "-axioms.txt",
        last_round={"classification": "PROGRESS", "new_module_count": 6, "new_theorem_count": 35,
                    "new_selected_report_count": 40, "retained_proof_sources_changed": False,
                    "root_and_registry_changed": True, "review_file": PREFIX + "-review.json", "remaining": remaining},
    )
    manifest["proved_components"] += COMPONENTS
    audit = read("AUDIT.txt")
    marker = "Remaining proof work:"
    assert audit.count(marker) == 1
    assert audit.split(marker, 1)[1].strip() == baseline["last_round"]["remaining"]
    note = ('\n2026-10-10 round-native-local-inverse: PROGRESS. Six new modules, 35 proved theorems and five definitions; 40 exact new kernel reports. All 747 baseline source/config hashes checked before registration; retained proofs and pins unchanged, only root and registry changed. Original shifted exponential has a true strict invertible derivative and genuine C-infinity coordinate local inverse. The constructed original native local logarithm has both actual local inverse laws with genuine chart-source control and native smoothness at every original vector. Original exponential is a local homeomorphism and open map; actual fibers are closed discrete and actual range is open. A true nilpotent finite exponential factor and polynomial-unit cancellation prove every original exponential period has zero original adjoint generator and native bracket. Original connectedness and actual open centralizers prove ker(Ad) is exactly the original center, and period curves lie entirely there. No covering map, global inverse, surjectivity, injectivity, BCH or elimination of central periods is claimed. Complete build terminal exit 0: ' + str(verified["build_jobs"]) + ' jobs. Kernel terminal exit 0: 3772 exact unique reports using only standard axioms; all retained axiom sets and six retained axiom-free reports unchanged. Scanned all 735 own and nine attributed PNT+ modules plus root/registry; 753 actual source/config hashes. New modules warning-free and oleans current. Fixed local paper objects match; no remote updates. Full StrongConjecture and prize target remain unproved. No unavoidable blocker. Review: round-native-local-inverse-review.json.\n\n')
    Path("AUDIT.txt").write_text(audit.split(marker, 1)[0] + note + marker + "\n" + remaining + "\n", encoding="utf-8")
    Path("BUILD-EVIDENCE.txt").write_bytes(b"=== COMPLETE BUILD OUTPUT ===\n" + blog + b"\n=== COMPLETE AXIOM OUTPUT ===\n" + alog + b"\n")
    write_obj(PREFIX + "-review.json", review)
    write_obj("verification-manifest.json", manifest)
    write_obj(PREFIX + "-preprint-local-check.json", fixed)
    write_obj(PREFIX + "-source-scan.json", {
        "project_modules": 735, "pntplus_modules": 9, "scanned_module_count": 744,
        "root_registry_scanned": True, "executable_banned_tokens": [], "new_unlimited_heartbeats": [],
        "new_disabled_linters": [], "retained_changed": review["retained_changed"],
        "root_imports_exact": True, "new_option_overrides": [],
    })
    write_obj(PREFIX + "-kernel-check.json", {
        "exact_unique_reports": 3772, "registered_names_exact": True, "new_names_exact": True,
        "retained_axiom_sets_unchanged": True, "allowed_axioms": sorted(ALLOWED),
        "axiom_free_reports": sorted(AXIOM_FREE),
    })
    write_obj(PREFIX + "-checks.json", {
        "baseline_hashes_verified_before_registration": 747, "previous_current_state_rechecked_before_edits": True,
        "retained_changed": review["retained_changed"], "retained_proof_sources_unchanged": True,
        "pins_and_attributed_sources_unchanged": True, "root_imports_exact": True,
        "registered_names_exact": True, "kernel_names_exact": True,
        "full_target_proved": False, "verified": verified,
    })
    print(json.dumps({"recorded": True, "verified": verified, "proved_components": len(manifest["proved_components"])}))


def recheck():
    baseline, registration, files, verified, blog, alog, fixed = checks()
    manifest = obj("verification-manifest.json")
    review = obj(PREFIX + "-review.json")
    result = obj(PREFIX + "-checks.json")
    assert manifest["files"] == files and all(digest(f["path"]) == f["sha256"] for f in files)
    assert review["verification"] == result["verified"] == verified
    assert review["new_theorem_count"] == 35 and review["new_selected_report_count"] == 40
    assert review["new_modules"] == registration["new_modules"]
    assert review["module_report_counts"] == registration["module_report_counts"]
    assert manifest["last_round"]["remaining"] == review["remaining"] == read("AUDIT.txt").split("Remaining proof work:", 1)[1].strip()
    assert len(manifest["proved_components"]) == 828 and manifest["proved_components"][-6:] == COMPONENTS
    assert manifest["full_target_proved"] is False and manifest["build_succeeded"] and manifest["axiom_check_succeeded"]
    assert obj(PREFIX + "-preprint-local-check.json") == fixed
    assert manifest["build_log"] == PREFIX + "-build.txt" and manifest["axiom_log"] == PREFIX + "-axioms.txt"
    for key, value in {
        "build_job_count": verified["build_jobs"], "hindman_module_count": verified["project_modules"],
        "pntplus_module_count": verified["pntplus_modules"], "selected_axiom_report_count": verified["axiom_reports"],
        "source_scan_module_count": verified["source_scan_modules"],
    }.items():
        assert manifest[key] == value
    assert Path("BUILD-EVIDENCE.txt").read_bytes() == b"=== COMPLETE BUILD OUTPUT ===\n" + blog + b"\n=== COMPLETE AXIOM OUTPUT ===\n" + alog + b"\n"
    scan = obj(PREFIX + "-source-scan.json")
    assert scan["scanned_module_count"] == 744 and not scan["executable_banned_tokens"] and not scan["new_option_overrides"]
    kernel = obj(PREFIX + "-kernel-check.json")
    assert kernel["exact_unique_reports"] == 3772 and kernel["retained_axiom_sets_unchanged"]
    result["fresh_final_recheck"] = {
        "source_config_hashes": len(files), "retained_only_root_registry_changed": True,
        "new_modules": len(registration["new_modules"]), "new_theorems": 35, "new_selected_declarations": 40,
        "all_source_modules_scanned": 744, "build_jobs": verified["build_jobs"], "kernel_exact_unique_reports": 3772,
        "new_oleans_current": True, "root_imports_exact": True, "source_theorem_names_match_registration": True,
        "allowed_standard_axioms_only": True, "retained_axiom_sets_unchanged": True, "combined_logs_exact": True,
        "review_audit_manifest_remaining_agree": True, "lean_actual": fixed["lean_actual"],
        "mathlib_actual": fixed["mathlib_actual"], "pntplus_actual": fixed["pntplus_actual"],
        "fixed_local_preprint_objects_match": True, "remote_updates_checked": False, "full_target_proved": False,
    }
    write_obj(PREFIX + "-checks.json", result)
    print(json.dumps(result["fresh_final_recheck"], ensure_ascii=False, indent=2))


if __name__ == "__main__":
    assert len(sys.argv) == 2 and sys.argv[1] in {"record", "recheck"}
    (record if sys.argv[1] == "record" else recheck)()
